    EXECUTE v_guard;
    d2_state := 'guard PASSED with PUBLIC execute';
  EXCEPTION WHEN OTHERS THEN
    d2_state := 'fired: ' || SQLERRM; d2_ok := SQLERRM LIKE '217 ABORTED%PUBLIC%';
  END;
  RAISE EXCEPTION 'D2_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'D2_ROLLBACK' THEN d2_state := 'scaffolding failed: ' || SQLERRM; d2_ok := false; END IF;
END;

-- D3: a generic increment_counter exists alongside.
BEGIN
  CREATE FUNCTION public.increment_counter(table_name text, row_id uuid, column_name text)
    RETURNS void LANGUAGE sql AS 'SELECT NULL';
  IF NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname = 'increment_counter') THEN
    d3_state := 'mutation did not land'; RAISE EXCEPTION 'D3_ROLLBACK';
  END IF;
  BEGIN
    EXECUTE v_guard;
    d3_state := 'guard PASSED with increment_counter present';
  EXCEPTION WHEN OTHERS THEN
    d3_state := 'fired: ' || SQLERRM; d3_ok := SQLERRM LIKE '217 ABORTED%increment_counter%';
  END;
  RAISE EXCEPTION 'D3_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'D3_ROLLBACK' THEN d3_state := 'scaffolding failed: ' || SQLERRM; d3_ok := false; END IF;
END;

-- D4: the body rewritten to use dynamic SQL.
BEGIN
  EXECUTE $mut$
    CREATE OR REPLACE FUNCTION public.increment_partner_metric(p_partner_id uuid, p_metric text)
    RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $b$
    BEGIN
      EXECUTE 'UPDATE public.featured_partners SET ' || p_metric || ' = ' || p_metric || ' + 1 WHERE id = $1'
        USING p_partner_id;
    END $b$
  $mut$;
  IF (SELECT prosrc FROM pg_proc WHERE oid = k_fn) !~* '\mexecute\M' THEN
    d4_state := 'mutation did not land'; RAISE EXCEPTION 'D4_ROLLBACK';
  END IF;
  BEGIN
    EXECUTE v_guard;
    d4_state := 'guard PASSED with dynamic SQL in the body';
  EXCEPTION WHEN OTHERS THEN
    d4_state := 'fired: ' || SQLERRM; d4_ok := SQLERRM LIKE '217 ABORTED%dynamic SQL%';
  END;
  RAISE EXCEPTION 'D4_ROLLBACK';
EXCEPTION WHEN OTHERS THEN
  IF SQLERRM <> 'D4_ROLLBACK' THEN d4_state := 'scaffolding failed: ' || SQLERRM; d4_ok := false; END IF;
END;

-- ── PART E: the premise ───────────────────────────────────────────────────

-- E1: the function the banner called does not exist, in any schema, under any
-- signature. This is the bug, measured on the database rather than inferred
-- from a PostgREST error.
SELECT count(*), coalesce(string_agg(n.nspname || '.' || p.proname, ', '), '(none)')
  INTO v_n, v_txt
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
 WHERE p.proname = 'increment_counter';
e1_state := v_n || ' functions named increment_counter: ' || v_txt;
e1_ok := v_n = 0;

-- ── PART F: baseline and identity ─────────────────────────────────────────

-- F1: no other generic incrementer is lying around that anon can run.
SELECT count(*), coalesce(string_agg(n.nspname || '.' || p.proname, ', ' ORDER BY p.proname), '(none)')
  INTO v_n, v_txt
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
 WHERE n.nspname = 'public'
   AND p.proname ~* '^(increment|decrement|bump|incr)'
   AND p.proname <> 'increment_partner_metric'
   AND has_function_privilege('anon', p.oid, 'EXECUTE');
f1_state := v_n || ' other anon-callable increment/decrement functions in public: ' || v_txt;
f1_ok := true;  -- informational: listed so a human reads each one; 217 does not depend on it

-- F3: the arms ran as anon/authenticated and came back to the editor's role.
f3_state := 'current_user ' || current_user || ', auth.uid() '
  || coalesce((SELECT auth.uid())::text, 'NULL');
f3_ok := current_user NOT IN ('anon', 'authenticated') AND (SELECT auth.uid()) IS NULL;

INSERT INTO reh_probe VALUES
  (1,  'A1 catalog: definer, search_path pinned, void, not PUBLIC, anon+authenticated', a1_state, a1_ok),
  (2,  'A2 scaffolding: an active and a paused throwaway partner', a2_state, a2_ok),
  (3,  'B1 POSITIVE: anon adds exactly one impression, nothing else', b1_state, b1_ok),
  (4,  'B2 POSITIVE: a signed-in user adds exactly one click, nothing else', b2_state, b2_ok),
  (5,  'B3 total_bookings is refused 22023 and unchanged', b3_state, b3_ok),
  (6,  'B4 every other column name, injection, NULL and empty refused 22023', b4_state, b4_ok),
  (7,  'B5 unknown partner is a no-op; no real partner''s counter moved', b5_state, b5_ok),
  (8,  'B6 a paused partner is not counted', b6_state, b6_ok),
  (9,  'B7 no other table reachable: names refused, one relation, no dynamic SQL', b7_state, b7_ok),
  (10, 'B8 anon''s direct UPDATE of the counters still changes nothing', b8_state, b8_ok),
  (11, 'B9 a temp-table decoy on search_path is not hijacked', b9_state, b9_ok),
  (12, 'D0 POSITIVE: 217''s guard passes on the real end state', d0_state, d0_ok),
  (13, 'D1 guard fires when search_path is unpinned', d1_state, d1_ok),
  (14, 'D2 guard fires when PUBLIC can execute', d2_state, d2_ok),
  (15, 'D3 guard fires when increment_counter exists', d3_state, d3_ok),
  (16, 'D4 guard fires when the body uses dynamic SQL', d4_state, d4_ok),
  (17, 'E1 PREMISE: no increment_counter exists anywhere', e1_state, e1_ok),
  (18, 'F1 INFO: other anon-callable increment functions in public', f1_state, f1_ok),
  (19, 'F2 BASELINE: no real partner has ever been counted', f2_state, f2_ok),
  (20, 'F3 IDENTITY: back to the editor''s role, auth.uid() NULL', f3_state, f3_ok);

END $outer$;

-- The one result set for the transaction. Every row must read PASS. 20 of 20.
SELECT seq, CASE WHEN coalesce(passed, false) THEN 'PASS' ELSE 'FAIL' END AS result, check_name,
       coalesce(detail, '(probe row missing)') AS detail
FROM reh_probe ORDER BY seq;

ROLLBACK;

-- ══════════════════════════════════════════════════════════════════════════
-- PART G: nothing escaped. RUN AS ITS OWN STATEMENT, AFTER THE ROLLBACK.
-- Expected BEFORE apply: no increment_partner_metric, no throwaway partner,
-- 217 not recorded.
-- ══════════════════════════════════════════════════════════════════════════

SELECT t.seq, CASE WHEN t.passed THEN 'PASS' ELSE 'FAIL' END AS result, t.check_name, t.detail
FROM (VALUES
  (1, 'G1 increment_partner_metric does not exist',
      coalesce(to_regprocedure('public.increment_partner_metric(uuid, text)')::text, '(absent, as expected)'),
      to_regprocedure('public.increment_partner_metric(uuid, text)') IS NULL),
  (2, 'G2 no throwaway partner escaped',
      (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh217-%')::text || ' partners',
      (SELECT count(*) FROM public.featured_partners WHERE slug LIKE 'reh217-%') = 0),
  (3, 'G3 no increment_counter escaped from D3',
      (SELECT count(*) FROM pg_proc WHERE proname = 'increment_counter')::text || ' functions',
      (SELECT count(*) FROM pg_proc WHERE proname = 'increment_counter') = 0),
  (4, 'G4 217 is NOT recorded as applied',
      (SELECT coalesce(string_agg(migration, ', '), '(not recorded, as expected)')
         FROM public.migrations_applied WHERE migration LIKE '217%'),
      (SELECT count(*) FROM public.migrations_applied WHERE migration LIKE '217%') = 0)
) AS t(seq, check_name, detail, passed)
ORDER BY t.seq;
